async def _deny_unapproved(
    tool_name: str,
    tool_input: dict[str, Any],
    context: ToolPermissionContext,
) -> PermissionResultAllow | PermissionResultDeny:
    """Deny any tool call not covered by the working directory's allow rules.

    Permission evaluation order: hooks → deny rules → permission mode →
    allow rules → canUseTool callback. If a call reaches this callback it
    was not auto-approved by the agent's settings, so we deny it. Mirrors
    the personal-assistant-dashboard pattern.
    """
    logger.info("denying unapproved tool call: %s", tool_name)
    return PermissionResultDeny(
        behavior="deny",
        message=f"Tool '{tool_name}' is not in the allowed permissions list.",
        interrupt=False,
    )


