        """Find the most recent session ID for the given working directory.

        Same algorithm as personal-assistant-dashboard: the SDK persists
        session JSONL files under ``~/.claude/projects/<project_key>/``;
        the latest by mtime is the session ID.
        """
        home = Path.home()
        project_key = str(cwd).replace("/", "-").replace("\\", "-").replace(":", "-")
        sessions_dir = home / ".claude" / "projects" / project_key
